    seen = {start}
    todo = [start]
    while todo:
        cur = todo.pop(0)
        for i in range(len(cur) - 1):
            if cur[i] != cur[i + 1]:
                z = next(q for q in 'ABC' if q != cur[i] and q != cur[i + 1])
                nxt = cur[:i] + z + cur[i + 2:]
                if nxt not in seen:
                    seen.add(nxt)
                    todo.append(nxt)
    assert len(start) == n
    assert int(out) == len(seen)


def test_dfs_set_difference(run, x):
    _, s = x.splitlines()
    out = run(x).strip()
    assert out.isdigit()
    reached = {s}
    stack = [s]
    alphabet = {'A', 'B', 'C'}
    while stack:
        t = stack.pop()
        for j, (a, b) in enumerate(zip(t, t[1:])):
            if a != b:
                c = next(iter(alphabet - {a, b}))
                u = t[:j] + c + t[j + 2:]
                if u not in reached:
                    reached.add(u)
                    stack.append(u)
    assert int(out) == len(reached)


