    initial = tuple(s)
    seen = {initial}
    pending = [initial]
    third = {('A', 'B'): 'C', ('B', 'A'): 'C', ('A', 'C'): 'B', ('C', 'A'): 'B', ('B', 'C'): 'A', ('C', 'B'): 'A'}
    while pending:
        state = pending.pop()
        for i in range(len(state) - 1):
            if state[i] != state[i + 1]:
                nxt = state[:i] + (third[(state[i], state[i + 1])],) + state[i + 2:]
                if nxt not in seen:
                    seen.add(nxt)
                    pending.append(nxt)
    assert int(answer) == len(seen)


def test_level_expansion(run, x):
    s = x.splitlines()[1]
    got = run(x).strip()
    assert got.isdigit()
    all_states = {s}
    frontier = {s}
    while frontier:
        following = set()
        for state in frontier:
            for i in range(len(state) - 1):
                left, right = state[i], state[i + 1]
                if left != right:
                    for c in 'ABC':
