def test_queue_reachability(run, x):
    s = x.splitlines()[1]
    output = run(x).strip()
    assert output.isdigit()
    states = {s}
    queue = [s]
    head = 0
    while head < len(queue):
        state = queue[head]
        head += 1
        for i in range(len(state) - 1):
            a = state[i]
            b = state[i + 1]
            if a == b:
                continue
            c = 'ABC'.replace(a, '').replace(b, '')
            candidate = state[:i] + c + state[i + 2:]
            if candidate not in states:
                states.add(candidate)
                queue.append(candidate)
    assert int(output) == len(states)


def test_all_operations_closure(run, x):
    lines = x.splitlines()
    s = lines[1]
    printed = run(x).strip()
    assert printed.isdigit()
    closure = {s}
    changed = True
    while changed:
        changed = False
        for state in list(closure):
            for i in range(len(state) - 1):
                if state[i] != state[i + 1]:
                    choices = [q for q in 'ABC' if q != state[i] and q != state[i + 1]]
                    next_state = state[:i] + choices[0] + state[i + 2:]
                    if next_state not in closure:
                        closure.add(next_state)
                        changed = True
    assert int(printed) == len(closure)

