def test_exhaustive_components_a(run, x):
    it = iter(map(int, x.split()))
    n, m = next(it), next(it)
    a = [next(it) for _ in range(n)]
    b = [next(it) for _ in range(n)]
    g = [[] for _ in range(n)]
    for _ in range(m):
        u, v = next(it)-1, next(it)-1
        g[u].append(v); g[v].append(u)
    best = -10**30
    for mask in range(1 << n):
        seen = [False]*n
        value = -sum(a[i] for i in range(n) if mask >> i & 1)
        for i in range(n):
            if not (mask >> i & 1) and not seen[i]:
                seen[i] = True; stack = [i]; total = 0
                while stack:
                    v = stack.pop(); total += b[v]
                    for w in g[v]:
                        if not seen[w] and not (mask >> w & 1):
                            seen[w] = True; stack.append(w)
                value += abs(total)
        best = max(best, value)
    s = run(x).strip()
    assert s and s.lstrip('-').isdigit()
    assert int(s) == best


