    n, a = data[0], data[1:]
    got = int(run(x).strip())
    if n > 8:
        return
    best = -10**30
    for chosen in range(1 << n):
        value = 0
        for i, v in enumerate(a, 1):
            smashed = any((chosen >> (d - 1)) & 1 and i % d == 0 for d in range(1, n + 1))
            if not smashed:
                value += v
        best = max(best, value)
    assert got == best


def test_divisor_closed_oracle(run, x):
