    n, a = data[0], data[1:]
    got = int(run(x).strip())
    if n > 8:
        return
    best = -10**30
    for mask in range(1 << n):
        valid = True
        for i in range(1, n + 1):
            if (mask >> (i - 1)) & 1:
                for d in range(1, i + 1):
                    if i % d == 0 and not ((mask >> (d - 1)) & 1):
