def test_small_direct_enumeration(run, x):
    data = list(map(int, x.split()))
    n, a = data[0], data[1:]
    got = int(run(x).strip())
    if n > 8:
        return
    answers = []
    for ops in range(1 << n):
        survivors = []
        for label in range(1, n + 1):
            alive = True
            for op in range(1, n + 1):
                if ((ops >> (op - 1)) & 1) and label % op == 0:
                    alive = False
                    break
            if alive:
                survivors.append(label - 1)
        answers.append(sum(a[k] for k in survivors))
    assert got == max(answers)


