    n, a = data[0], data[1:]
    output = run(x)
    best = -10**30
    def search(operation, smashed):
        nonlocal best
        if operation > n:
            best = max(best, sum(a[i - 1] for i in range(1, n + 1) if i not in smashed))
            return
        search(operation + 1, smashed)
        search(operation + 1, smashed | set(range(operation, n + 1, operation)))
    search(1, set())
    assert int(output.strip()) == best

def test_bfs_minimum(run, x):
    from collections import deque
    z = list(map(int, x.split())); n = z[0]; a = tuple(sorted(z[1:1+n])); b = tuple(z[1+n:])
    q = deque([(a, b, 0)]); seen = {(a, b)}; ans = None
    while q:
        h, p, d = q.popleft()
        if p == tuple(range(1, n+1)):
            ans = d; break
        for v in set(h):
            t = list(h); t.remove(v); nh = tuple(sorted(t + [p[0]])); np = p[1:] + (v,)
            if (nh, np) not in seen:
                seen.add((nh, np)); q.append((nh, np, d+1))
    s = run(x).strip()
    assert s.lstrip('-').isdigit()
    assert int(s) == ans

