    want = []
    for k in range(1, (n + 1) // 2 + 1):
        best = 10**18
        for mask in range(1 << n):
            if mask.bit_count() < k or mask & (mask << 1):
                continue
            cost = 0
            for i in range(n):
                if not (mask >> i & 1):
                    lim = 10**9
                    if i and (mask >> (i - 1) & 1): lim = min(lim, a[i - 1] - 1)
