def test_bitset_exact_minimum(run, x):
    out = run(x).strip()
    assert len(out.split()) == 1
    got = int(out)
    lines = x.splitlines()
    n, k = map(int, lines[0].split())
    vals = set(map(int, lines[1].split()))
    if n in vals:
        expected = 1
    else:
        lo = [n - a for a in vals if a < n]
        hi = [a - n for a in vals if a > n]
        if not lo or not hi:
            expected = -1
        else:
            limit = min(p // __import__('math').gcd(p, q) + q // __import__('math').gcd(p, q) for p in lo for q in hi)
            bits = 1
            expected = -1
            for m in range(1, limit + 1):
                nxt = 0
                for a in vals:
                    nxt |= bits << a
                bits = nxt
                if (bits >> (n * m)) & 1:
                    expected = m
                    break
    assert got == expected


