        expected = 1
    elif not any(a < n for a in vals) or not any(a > n for a in vals):
        expected = -1
    else:
        import math
        limit = min((n-a)//math.gcd(n-a, b-n) + (b-n)//math.gcd(n-a, b-n) for a in vals if a < n for b in vals if b > n)
        expected = -1
        for total in range(2, limit + 1):
            def possible(i, left_count, left_sum):
                if i == len(vals) - 1:
                    return left_sum + left_count * vals[i] == total * n
                for c in range(left_count + 1):
                    if possible(i + 1, left_count - c, left_sum + c * vals[i]):
                        return True
                return False
            if possible(0, total, 0):
                expected = total
                break
    assert got == expected


