                legal = typ == 'ATK' and p >= s or typ == 'DEF' and p > s
                if live & (1 << j) and legal:
                    r = max(r, (p - s if typ == 'ATK' else 0) + dp(u | (1 << i), live ^ (1 << j)))
        return r
    out = run(x).strip()
    assert out and (out.isdigit() or (out[0] == '-' and out[1:].isdigit()))
    assert int(out) == dp(0, (1 << n) - 1)

def test_all_legal_sequences(run, x):
    from functools import lru_cache
    parts = x.split(); n, m = map(int, parts[:2]); pos = 2
    ji = []
    for _ in range(n):
        ji.append((parts[pos], int(parts[pos + 1]))); pos += 2
    ci = [int(q) for q in parts[pos:pos + m]]
    @lru_cache(None)
    def search(chosen, remaining):
        value = 0
        for a, p in enumerate(ci):
            if chosen & (1 << a):
                continue
            if remaining == 0:
                value = max(value, p + search(chosen | (1 << a), 0))
            else:
                for b, (kind, s) in enumerate(ji):
                    if remaining & (1 << b) and (p >= s if kind == 'ATK' else p > s):
                        value = max(value, (p - s if kind == 'ATK' else 0) + search(chosen | (1 << a), remaining & ~(1 << b)))
        return value
    got = run(x).strip()
    assert got and (got.isdigit() or (got[0] == '-' and got[1:].isdigit()))
    assert int(got) == search(0, (1 << n) - 1)

def test_optimal_battle_value(run, x):
    from functools import lru_cache
    w = x.split(); n = int(w[0]); m = int(w[1]); z = 2
    enemies = []
    for _ in range(n):
        enemies += [(w[z], int(w[z + 1]))]; z += 2
    mine = [int(v) for v in w[z:z + m]]
    @lru_cache(None)
    def go(mask, alive):
        best = 0
        for i in range(m):
            if mask & (1 << i):
                continue
            p = mine[i]
            if alive == 0:
                best = max(best, p + go(mask | (1 << i), 0))
            for j in range(n):
                if not alive & (1 << j):
                    continue
                t, s = enemies[j]
                if (t == 'ATK' and p >= s) or (t == 'DEF' and p > s):
                    best = max(best, (p - s if t == 'ATK' else 0) + go(mask | (1 << i), alive ^ (1 << j)))
        return best
    answer = run(x).strip()
    assert answer and (answer.isdigit() or (answer[0] == '-' and answer[1:].isdigit()))
    assert int(answer) == go(0, (1 << n) - 1)

def test_direct_rule_dp(run, x):
    from functools import lru_cache
    q = x.split(); n, m = int(q[0]), int(q[1]); p = 2
    targets = []
    for _ in range(n):
        targets.append((q[p], int(q[p + 1]))); p += 2
    hand = list(map(int, q[p:p + m]))
    @lru_cache(None)
    def rec(used, alive):
        best = 0
        for i, strength in enumerate(hand):
            if used >> i & 1:
                continue
            newused = used | (1 << i)
            if alive == 0:
                best = max(best, strength + rec(newused, 0))
            for j, (position, foe) in enumerate(targets):
                if alive >> j & 1 and (strength >= foe if position == 'ATK' else strength > foe):
                    best = max(best, (strength - foe if position == 'ATK' else 0) + rec(newused, alive ^ (1 << j)))
        return best
    result = run(x).strip()
    assert result and (result.isdigit() or (result[0] == '-' and result[1:].isdigit()))
    assert int(result) == rec(0, (1 << n) - 1)

def test_zero_and_tie_oracle(run, x):
    from functools import lru_cache
    a = x.split(); n, m = map(int, a[:2]); at = 2
    foes = []
    for _ in range(n):
        foes.append((a[at], int(a[at + 1]))); at += 2
    cards = [int(a[at + i]) for i in range(m)]
    @lru_cache(None)
    def opt(used, alive):
        best = 0
        for i, card in enumerate(cards):
            if used & (1 << i):
                continue
            nxt = used | (1 << i)
            if not alive:
                best = max(best, card + opt(nxt, 0))
            for j, (kind, val) in enumerate(foes):
                if alive & (1 << j) and (card >= val if kind == 'ATK' else card > val):
                    best = max(best, (card - val if kind == 'ATK' else 0) + opt(nxt, alive ^ (1 << j)))
        return best
    value = run(x).strip()
    assert value and (value.isdigit() or (value[0] == '-' and value[1:].isdigit()))
    assert int(value) == opt(0, (1 << n) - 1)

def test_end_phase_choice(run, x):
    from functools import lru_cache
    s = x.split(); n = int(s[0]); m = int(s[1]); i = 2
    rivals = []
    for _ in range(n):
        rivals.append((s[i], int(s[i + 1]))); i += 2
    own = list(map(int, s[i:i + m]))
    @lru_cache(None)
    def value(used, alive):
        best = 0
        for c, power in enumerate(own):
            if used & (1 << c):
                continue
            u = used | (1 << c)
            if alive == 0:
                best = max(best, power + value(u, 0))
            for r, (kind, strength) in enumerate(rivals):
                if alive & (1 << r) and ((kind == 'ATK' and power >= strength) or (kind == 'DEF' and power > strength)):
                    damage = power - strength if kind == 'ATK' else 0
                    best = max(best, damage + value(u, alive ^ (1 << r)))
        return best
    text = run(x).strip()
    assert text and (text.isdigit() or (text[0] == '-' and text[1:].isdigit()))
    assert int(text) == value(0, (1 << n) - 1)

def test_complete_small_oracle(run, x):
    from functools import lru_cache
    data = x.split(); n, m = int(data[0]), int(data[1]); index = 2
    opponents = []
    for _ in range(n):
        opponents.append((data[index], int(data[index + 1]))); index += 2
    attacks = list(map(int, data[index:index + m]))
    @lru_cache(None)
    def best(used, alive):
        result = 0
        for i, attack in enumerate(attacks):
            if used & (1 << i):
                continue
            if alive == 0:
                result = max(result, attack + best(used | (1 << i), 0))
            else:
                for j, (mode, strength) in enumerate(opponents):
                    allowed = attack >= strength if mode == 'ATK' else attack > strength
                    if alive & (1 << j) and allowed:
                        result = max(result, (attack - strength if mode == 'ATK' else 0) + best(used | (1 << i), alive ^ (1 << j)))
        return result
    returned = run(x).strip()
    assert returned and (returned.isdigit() or (returned[0] == '-' and returned[1:].isdigit()))
    assert int(returned) == best(0, (1 << n) - 1)

def test_state_space_oracle(run, x):
    from functools import lru_cache
    tokens = x.split(); n, m = map(int, tokens[:2]); cursor = 2
    jiro = []
    for _ in range(n):
        jiro.append((tokens[cursor], int(tokens[cursor + 1]))); cursor += 2
    ciel = [int(t) for t in tokens[cursor:cursor + m]]
    @lru_cache(None)
    def dfs(used, alive):
        maximum = 0
        for i, power in enumerate(ciel):
            if used & (1 << i):
                continue
            next_used = used | (1 << i)
            if alive == 0:
                maximum = max(maximum, power + dfs(next_used, 0))
                continue
            for j, (position, strength) in enumerate(jiro):
                if not alive & (1 << j):
                    continue
                if position == 'ATK' and power >= strength:
                    maximum = max(maximum, power - strength + dfs(next_used, alive ^ (1 << j)))
                if position == 'DEF' and power > strength:
                    maximum = max(maximum, dfs(next_used, alive ^ (1 << j)))
        return maximum
    output = run(x).strip()
    assert output and (output.isdigit() or (output[0] == '-' and output[1:].isdigit()))
    assert int(output) == dfs(0, (1 << n) - 1)

