    if n == 2:
        good = sum(1 for u in range(1, a[0] + 1) for v in range(1, a[1] + 1) if u < v)
        expected = (1 + good * pow(a[0] * a[1], 1000000005, 1000000007)) % 1000000007
        assert out == expected
    else:
