def test_bruteforce_subsequences(run, x):
    from itertools import product, combinations
    out = int(run(x).strip())
    z = list(map(int, x.split())); n = z[0]; a = z[1:]
    total = 1
    for q in a: total *= q
    if total > 100000:
        assert 0 <= out < 1000000007
        return
    acc = 0
    for y in product(*[range(1, q + 1) for q in a]):
        best = 0
        for r in range(1, n + 1):
            for ix in combinations(range(n), r):
                if all(y[ix[j]] < y[ix[j + 1]] for j in range(r - 1)):
                    best = r
        acc += best
    assert out == acc * pow(total, 1000000005, 1000000007) % 1000000007


def test_bruteforce_quadratic_lis(run, x):
    from itertools import product
    out = int(run(x).strip())
    z = list(map(int, x.split())); n = z[0]; a = z[1:]
    total = 1
    for q in a: total *= q
    if total > 100000:
        assert 0 <= out < 1000000007
        return
    s = 0
    for y in product(*[range(1, q + 1) for q in a]):
        d = [1] * n
        for i in range(n):
            for j in range(i):
                if y[j] < y[i]: d[i] = max(d[i], d[j] + 1)
        s += max(d)
    assert out == s * pow(total, 1000000005, 1000000007) % 1000000007


def test_bruteforce_tails_lis(run, x):
    from itertools import product
    from bisect import bisect_left
    out = int(run(x).strip())
    z = list(map(int, x.split())); a = z[1:]
    total = 1
    for q in a: total *= q
    if total > 100000:
        assert 0 <= out < 1000000007
        return
    s = 0
    for y in product(*[range(1, q + 1) for q in a]):
        tails = []
        for v in y:
            i = bisect_left(tails, v)
            if i == len(tails): tails.append(v)
            else: tails[i] = v
        s += len(tails)
    assert out == s * pow(total, 1000000005, 1000000007) % 1000000007


