def test_small_space_direct_average(run, x):
    from itertools import product
    out = int(run(x).strip())
    z = list(map(int, x.split())); n = z[0]; a = z[1:]
    m = 1
    for v in a: m *= v
    if m > 100000:
        assert 0 <= out < 1000000007
        return
    value = 0
    for y in product(*map(lambda v: range(1, v + 1), a)):
        best = 1
        for mask in range(1, 1 << n):
            seq = [y[i] for i in range(n) if mask >> i & 1]
            if all(seq[i] < seq[i + 1] for i in range(len(seq) - 1)):
                best = max(best, len(seq))
        value += best
    assert out == value * pow(m, 1000000005, 1000000007) % 1000000007


def test_small_space_exact_fraction(run, x):
    from itertools import product
    out = int(run(x).strip())
    z = list(map(int, x.split())); n = z[0]; a = z[1:]
    den = 1
    for v in a: den *= v
    if den > 100000:
        assert 0 <= out < 1000000007
        return
    num = 0
    for y in product(*[range(1, v + 1) for v in a]):
        lengths = [1] * n
        for i in range(n):
            lengths[i] = 1 + max([lengths[j] for j in range(i) if y[j] < y[i]] or [0])
        num += max(lengths)
    assert (out * den - num) % 1000000007 == 0


def test_small_space_lis_definition(run, x):
    from itertools import product
    out = int(run(x).strip())
    z = list(map(int, x.split())); n = z[0]; a = z[1:]
    den = 1
