    if den > 100000:
        assert 0 <= out < 1000000007
        return
    num = 0
    for y in product(*[range(1, v + 1) for v in a]):
        best = 1
        for mask in range(1, 1 << n):
            last = None; ok = True; cnt = 0
            for i in range(n):
                if mask & (1 << i):
                    if last is not None and last >= y[i]: ok = False
                    last = y[i]; cnt += 1
            if ok and cnt > best: best = cnt
        num += best
    assert out == num * pow(den, 1000000005, 1000000007) % 1000000007

