    n, m = map(int, lines[0].split())
    grid = lines[3:3+n]
    ans = int(run(x).strip())
    assert 1 <= ans <= sum(row.count('.') for row in grid)


def test_isolated_start_has_one(run, x):
    lines = x.splitlines()
    n, m = map(int, lines[0].split())
    r, c = map(int, lines[1].split())
    g = lines[3:3+n]
    ok = True
    for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
        a, b = r-1+dr, c-1+dc
        if 0 <= a < n and 0 <= b < m and g[a][b] == '.': ok = False
    if ok: assert int(run(x).strip()) == 1
    else: assert int(run(x).strip()) >= 1


def test_one_dimensional_oracle(run, x):
    lines=x.splitlines(); n,m=map(int,lines[0].split()); r,c=map(int,lines[1].split()); L,R=map(int,lines[2].split()); g=lines[3:3+n]
    if n == 1:
        total=1
        j=c-2
        while j>=0 and g[0][j]=='.' and c-1-j<=L: total+=1; j-=1
        j=c
        while j<m and g[0][j]=='.' and j-(c-1)<=R: total+=1; j+=1
        assert int(run(x).strip()) == total
    else:
        assert int(run(x).strip()) >= 1


def test_exact_state_enumeration_a(run, x):
    z=x.splitlines(); n,m=map(int,z[0].split()); r,c=map(int,z[1].split()); L,R=map(int,z[2].split()); g=z[3:3+n]; L=min(L,n*m); R=min(R,n*m); q=[(r-1,c-1,0,0)]; seen=set(q); cells={(r-1,c-1)}
    for a,b,l,rr in q:
        for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
            u,v=a+da,b+db; nl=l+(db==-1); nr=rr+(db==1)
            if 0<=u<n and 0<=v<m and g[u][v]=='.' and nl<=L and nr<=R and (u,v,nl,nr) not in seen: seen.add((u,v,nl,nr)); q.append((u,v,nl,nr)); cells.add((u,v))
