def test_prefix_dp_exact(run, x):
    first, s = x.strip().splitlines()
    n, a, b = map(int, first.split())
    dp = [0] + [10**18] * n
    for end in range(1, n + 1):
        dp[end] = dp[end - 1] + a
        for start in range(end):
            if s[start:end] in s[:start]:
                dp[end] = min(dp[end], dp[start] + b)
    assert int(run(x).strip()) == dp[n]


def test_last_piece_oracle(run, x):
    line, word = x.strip().splitlines()
    length, single, prior = map(int, line.split())
    best = [0]
    for stop in range(1, length + 1):
        value = best[stop - 1] + single
        for cut in range(stop):
            block = word[cut:stop]
            if block in word[:cut]:
                value = min(value, best[cut] + prior)
        best.append(value)
    assert int(run(x).strip()) == best[-1]


def test_all_suffixes_exact(run, x):
    header, s = x.strip().splitlines()
    n, a, b = map(int, header.split())
    cost = [0] + [None] * n
    for i in range(1, n + 1):
        candidates = [cost[i - 1] + a]
        for j in range(i):
            if s[j:i] in s[:j]:
                candidates.append(cost[j] + b)
        cost[i] = min(candidates)
    assert int(run(x).strip()) == cost[n]


def test_direct_segmentation_dp(run, x):
    nums, text = x.strip().splitlines()
    n, a, b = map(int, nums.split())
    answer = [0] + [10**30] * n
    for produced in range(n):
        answer[produced + 1] = min(answer[produced + 1], answer[produced] + a)
        for nxt in range(produced + 1, n + 1):
            if text[produced:nxt] in text[:produced]:
                answer[nxt] = min(answer[nxt], answer[produced] + b)
    assert int(run(x).strip()) == answer[n]


def test_forward_transition_oracle(run, x):
    head, s = x.strip().splitlines()
    n, a, b = map(int, head.split())
    d = [10**18] * (n + 1)
    d[0] = 0
    for left in range(n):
        d[left + 1] = min(d[left + 1], d[left] + a)
        for right in range(left + 1, n + 1):
            part = s[left:right]
            if part in s[:left]:
                d[right] = min(d[right], d[left] + b)
    assert int(run(x).strip()) == d[-1]


def test_minimum_encoding_cost(run, x):
    h, s = x.strip().splitlines()
    n, a, b = map(int, h.split())
    opt = [0]
    for r in range(1, n + 1):
        opt.append(opt[r - 1] + a)
        for l in range(r):
            if s[l:r] in s[0:l]:
                opt[r] = min(opt[r], opt[l] + b)
    assert int(run(x).strip()) == opt[n]


def test_copy_rule_exact(run, x):
    fields, s = x.strip().splitlines()
    n, a, b = map(int, fields.split())
    values = [0 for _ in range(n + 1)]
    for end in range(1, n + 1):
        values[end] = values[end - 1] + a
        for begin in range(end):
            earlier = s[:begin]
            if s[begin:end] in earlier:
                values[end] = min(values[end], values[begin] + b)
    assert int(run(x).strip()) == values[n]


def test_exhaustive_final_block(run, x):
    row, s = x.strip().splitlines()
    n, a, b = map(int, row.split())
    memo = {0: 0}
    def solve(end):
        if end in memo:
            return memo[end]
        result = solve(end - 1) + a
        for start in range(end):
            if s[start:end] in s[:start]:
                result = min(result, solve(start) + b)
        memo[end] = result
        return result
    assert int(run(x).strip()) == solve(n)


def test_answer_is_valid_integer(run, x):
    result = run(x).strip()
    assert result
    value = int(result)
    assert str(value) == result
    assert value > 0


def test_partition_cost_exact(run, x):
    first, s = x.strip().splitlines()
    n, a, b = map(int, first.split())
    inf = 10**18
    dp = [inf] * (n + 1)
    dp[0] = 0
    for end in range(1, n + 1):
        for start in range(end):
            if end == start + 1:
                dp[end] = min(dp[end], dp[start] + a)
            if s[start:end] in s[:start]:
                dp[end] = min(dp[end], dp[start] + b)
    assert int(run(x).strip()) == dp[n]

