                    cost += b if i and p[0] == q[i - 1][1] else a
            best = min(best, cost)
    assert run(x).strip() == str(best)


def test_near_equal_fares(run, x):
    import itertools
    z = x.split()
    n, a, b, k, f = map(int, z[:5])
    q = list(zip(z[5::2], z[6::2]))
    routes = {tuple(sorted(p)) for p in q}
    best = 10**18
    for size in range(min(k, len(routes)) + 1):
        for chosen in itertools.combinations(routes, size):
            chosen = set(chosen)
            cost = size * f
            for i, p in enumerate(q):
                if tuple(sorted(p)) not in chosen:
                    cost += b if i and p[0] == q[i - 1][1] else a
            best = min(best, cost)
    assert run(x).strip() == str(best)

