    n, m = map(int, lines[0].split())
    if m > 20:
        return
    initial = list(map(int, lines[1].split()))
    controls = [list(map(int, line.split()))[1:] for line in lines[2:2 + m]]
    possible = False
    for mask in range(1 << m):
        doors = initial[:]
        for s in range(m):
            if (mask >> s) & 1:
                for room in controls[s]:
                    doors[room - 1] ^= 1
        if all(doors):
            possible = True
            break
    assert run(x).strip() == ('YES' if possible else 'NO')

def test_bruteforce_parities(run, x):
