    answer = False
    for chosen in range(1 << m):
        good = True
        for room in range(1, n + 1):
            flips = sum(((chosen >> s) & 1) for s in range(m) if room in switches[s])
            if (doors[room - 1] ^ (flips & 1)) != 1:
                good = False
                break
        if good:
            answer = True
            break
    assert run(x).strip() == ('YES' if answer else 'NO')

def test_exhaustive_sets(run, x):
