    winning = any(all(start[r] ^ (sum((mask >> s) & 1 for s in range(m) if r + 1 in entries[s]) % 2) for r in range(n)) for mask in range(1 << m))
    assert run(x).strip() == ('YES' if winning else 'NO')

def test_direct_room_simulation(run, x):
