def test_small_instance_oracle(run, x):
    lines = x.strip().splitlines()
    n, m = (int(a) for a in lines[0].split())
    if m > 20:
        return
    base = [int(a) for a in lines[1].split()]
    links = [list(map(int, lines[i].split()))[1:] for i in range(2, m + 2)]
    can_open = False
    for mask in range(2 ** m):
        final = []
        for room in range(1, n + 1):
            value = base[room - 1]
            for switch in range(m):
                if mask & (2 ** switch) and room in links[switch]:
                    value ^= 1
            final.append(value)
