            can_open = True
    assert run(x).strip() == ('YES' if can_open else 'NO')

def test_exhaustive_specification(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    if m > 20:
        return
    locked_state = list(map(int, lines[1].split()))
    switch_rooms = []
    for line in lines[2:2 + m]:
        p = list(map(int, line.split()))
        switch_rooms.append(p[1:])
    expected = 'NO'
    for choices in range(1 << m):
        state = locked_state[:]
        for switch in range(m):
            if choices & (1 << switch):
                for room in switch_rooms[switch]:
                    state[room - 1] ^= 1
        if all(v == 1 for v in state):
            expected = 'YES'
            break
    assert run(x).strip() == expected

def test_bruteforce_product(run, x):
    from itertools import product
    lines = x.splitlines()
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    controls = [set(map(int, lines[i + 2].split()[1:])) for i in range(m)]
    possible = False
    for bits in product((0, 1), repeat=m):
        if all((a[r - 1] ^ sum(bits[j] for j in range(m) if r in controls[j]) % 2) == 1 for r in range(1, n + 1)):
            possible = True
    assert run(x).strip() == ('YES' if possible else 'NO')

def test_explicit_masks(run, x):
    lines = x.splitlines()
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    sw = [set(map(int, z.split()[1:])) for z in lines[2:2 + m]]
    ok = False
    for mask in range(1 << m):
        good = True
        for room in range(1, n + 1):
            flips = 0
            for j in range(m):
                if (mask >> j) & 1 and room in sw[j]:
                    flips ^= 1
            if (a[room - 1] ^ flips) != 1:
                good = False
                break
        ok |= good
    assert run(x).strip() == ('YES' if ok else 'NO')

def test_constraint_intersection(run, x):
    lines = x.splitlines()
    n, m = map(int, lines[0].split())
    states = list(map(int, lines[1].split()))
    owners = [[] for _ in range(n)]
    for s, line in enumerate(lines[2:2 + m]):
        for room in map(int, line.split()[1:]):
            owners[room - 1].append(s)
    candidates = set(range(1 << m))
    for room, initial in enumerate(states):
        need = 1 ^ initial
        candidates = {mask for mask in candidates if (sum((mask >> s) & 1 for s in owners[room]) & 1) == need}
    assert run(x).strip() == ('YES' if candidates else 'NO')

def test_toggle_simulation(run, x):
    lines = x.splitlines()
    n, m = map(int, lines[0].split())
    initial = list(map(int, lines[1].split()))
    switches = [list(map(int, line.split()[1:])) for line in lines[2:2 + m]]
    answer = False
    for mask in range(1 << m):
        doors = initial[:]
        for s in range(m):
            if mask & (1 << s):
                for room in switches[s]:
                    doors[room - 1] ^= 1
        if all(doors):
            answer = True
    assert run(x).strip() == ('YES' if answer else 'NO')

def test_subset_enumeration(run, x):
    from itertools import combinations
    lines = x.splitlines()
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    sets = [set(map(int, line.split()[1:])) for line in lines[2:2 + m]]
    ok = False
    for size in range(m + 1):
        for chosen in combinations(range(m), size):
            if all(a[r - 1] ^ (sum(r in sets[s] for s in chosen) & 1) for r in range(1, n + 1)):
                ok = True
    assert run(x).strip() == ('YES' if ok else 'NO')

def test_room_parities(run, x):
    lines = x.splitlines()
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    membership = [set(map(int, line.split()[1:])) for line in lines[2:2 + m]]
    feasible = False
    for assignment in range(1 << m):
        required = [1 ^ value for value in a]
        actual = []
        for room in range(1, n + 1):
            parity = 0
            for switch in range(m):
                if assignment & (1 << switch) and room in membership[switch]:
                    parity ^= 1
            actual.append(parity)
        if actual == required:
            feasible = True
    assert run(x).strip() == ('YES' if feasible else 'NO')

def test_token_parser_oracle(run, x):
    data = list(map(int, x.split()))
    p = 0
    n, m = data[p], data[p + 1]
    p += 2
    doors = data[p:p + n]
    p += n
    affected = [[] for _ in range(n)]
    for switch in range(m):
        count = data[p]
        p += 1
        for room in data[p:p + count]:
            affected[room - 1].append(switch)
        p += count
    good = any(all((doors[i] ^ (sum((mask >> s) & 1 for s in affected[i]) & 1)) == 1 for i in range(n)) for mask in range(1 << m))
    assert run(x).strip() == ('YES' if good else 'NO')

def test_all_assignments_witness(run, x):
    lines = x.splitlines()
    n, m = map(int, lines[0].split())
    start = list(map(int, lines[1].split()))
    incidence = [[False] * m for _ in range(n)]
    for j, line in enumerate(lines[2:2 + m]):
        for room in map(int, line.split()[1:]):
            incidence[room - 1][j] = True
    witness = False
    for bits in range(1 << m):
        valid = True
        for i in range(n):
            value = start[i]
            for j in range(m):
                if incidence[i][j] and ((bits >> j) & 1):
                    value = 1 - value
            valid = valid and value == 1
        witness = witness or valid
    assert run(x).strip() == ('YES' if witness else 'NO')

def test_required_xor_check(run, x):
    lines = x.splitlines()
    n, m = map(int, lines[0].split())
    status = list(map(int, lines[1].split()))
    by_room = [[] for _ in range(n)]
    for switch, line in enumerate(lines[2:2 + m]):
        for room in map(int, line.split()[1:]):
            by_room[room - 1].append(switch)
    solutions = []
    for mask in range(1 << m):
        if all((sum((mask >> q) & 1 for q in by_room[i]) & 1) == (1 ^ status[i]) for i in range(n)):
            solutions.append(mask)
    assert run(x).strip() == ('YES' if len(solutions) > 0 else 'NO')

def test_output_and_direct_oracle(run, x):
    output = run(x).strip()
    assert output in {'YES', 'NO'}
    lines = x.splitlines()
    n, m = map(int, lines[0].split())
    values = list(map(int, lines[1].split()))
    switch_rooms = [set(map(int, line.split()[1:])) for line in lines[2:2 + m]]
    possible = False
    for mask in range(1 << m):
        final = []
        for room in range(1, n + 1):
            toggles = sum(bool(mask & (1 << j)) and room in switch_rooms[j] for j in range(m))
            final.append(values[room - 1] ^ (toggles % 2))
        possible = possible or final == [1] * n
    assert output == ('YES' if possible else 'NO')

