        assert out == 'YES'


def test_exhaustive_parent_oracle(run, x):
    data = list(map(int, x.split()))
    n, c = data[0], data[1:]
    out = run(x).strip()
    assert out in {'YES', 'NO'}
    if n > 9:
        return
    possible = False
    for root in range(n):
        if c[root] != n:
            continue
        rem = [v - 1 for v in c]
        kids = [0] * n
        order = sorted((i for i in range(n) if i != root), key=lambda i: -c[i])
        def search(k):
            if k == len(order):
                return all(rem[i] == 0 and kids[i] != 1 for i in range(n))
            node = order[k]
            for parent in range(n):
                if c[parent] > c[node] and rem[parent] >= c[node]:
                    rem[parent] -= c[node]
                    kids[parent] += 1
                    if search(k + 1):
                        return True
                    kids[parent] -= 1
                    rem[parent] += c[node]
            return False
        if search(0):
            possible = True
            break
    assert out == ('YES' if possible else 'NO')


