    z = list(map(int, x.split()))
    n, c = z[0], z[1:]
    answer = run(x).strip()
    assert answer in ('YES', 'NO')
    if n > 9:
        return
    ok = False
    for r in range(n):
        if c[r] != n:
            continue
        left = [q - 1 for q in c]
        degree = [0] * n
        nodes = sorted([i for i in range(n) if i != r], key=lambda i: c[i], reverse=True)
        def place(pos):
            if pos == len(nodes):
                return all(left[i] == 0 and degree[i] != 1 for i in range(n))
            v = nodes[pos]
            for p in range(n):
                if c[p] > c[v] and left[p] >= c[v]:
                    left[p] -= c[v]
                    degree[p] += 1
                    if place(pos + 1):
                        return True
                    degree[p] -= 1
                    left[p] += c[v]
            return False
        if place(0):
            ok = True
            break
    assert answer == ('YES' if ok else 'NO')


