def test_exhaustive_feasibility(run, x):
    z = list(map(int, x.split()))
    n, a = z[0], z[1:]
    good = [False] * (1 << n)
    for m in range(1, 1 << n):
        k = m.bit_count()
        for r in range(n):
            if not (m >> r & 1) or a[r] != k:
                continue
            rest = m ^ (1 << r)
            memo = {}
            def parts(s):
                if not s:
                    return 0
                if s in memo:
                    return memo[s]
                bit = s & -s
                best = -100
                t = s
                while t:
                    if t & bit and good[t]:
                        best = max(best, 1 + parts(s ^ t))
                    t = (t - 1) & s
                memo[s] = best
                return best
            if (k == 1 and rest == 0) or (k > 1 and parts(rest) >= 2):
                good[m] = True
                break
    assert run(x).strip() == ('YES' if good[-1] else 'NO')

