        assert out == '-1'
        assert out.split() == ['-1']


def test_direct_validity_oracle(run, x):
    out = run(x).strip()
    lines = x.splitlines()
    n, m = map(int, lines[0].split())
    g = lines[1:1 + n]
    def contiguous(seq):
        marks = [i for i, ch in enumerate(seq) if ch == '#']
        return not marks or len(marks) == marks[-1] - marks[0] + 1
    ok = all(contiguous(row) for row in g)
    ok = ok and all(contiguous([g[i][j] for i in range(n)]) for j in range(m))
    empty_rows = any('#' not in row for row in g)
    empty_cols = any(all(g[i][j] == '.' for i in range(n)) for j in range(m))
    ok = ok and empty_rows == empty_cols
    if not ok:
        assert out == '-1'

