 R=any('#' not in r for r in g);C=any(all(r[j]=='.' for r in g) for j in range(m))
 B=any('.' in r.strip('.') for r in g) or any('.' in ''.join(r[j] for r in g).strip('.') for j in range(m))
 if R!=C or B:e=-1
 else:
  z={(i,j) for i in range(n) for j in range(m) if g[i][j]=='#'};e=0
  while z:
   e+=1;q=[z.pop()]
   for u,v in q:
    for p in ((u-1,v),(u+1,v),(u,v-1),(u,v+1)):
     if p in z:z.remove(p);q.append(p)
 assert run(x).strip()==str(e)

