def test_exhaustive_edges(run, x):
    vals = list(map(int, x.split()))
    n, a = vals[0], vals[1:]
    d = [abs(a[i] - a[i + 1]) for i in range(n - 1)]
    want = max(sum((1 if (k - l) % 2 == 0 else -1) * d[k] for k in range(l, r + 1)) for l in range(n - 1) for r in range(l, n - 1))
    assert int(run(x).strip()) == want

def test_exhaustive_toggle(run, x):
    vals = list(map(int, x.split())
)
    n, a = vals[0], vals[1:]
    best = -10**30
    for l in range(n - 1):
        total = 0
        sign = 1
        for r in range(l, n - 1):
            total += sign * abs(a[r] - a[r + 1])
            best = max(best, total)
            sign = -sign
    assert int(run(x).strip()) == best

def test_original_indices(run, x):
