def test_all_interval_values(run, x):
    p = list(map(int, x.split()))
    n, a = p[0], p[1:]
    values = []
    for left in range(n - 1):
        acc = 0
        for right in range(left, n - 1):
            delta = abs(a[right] - a[right + 1])
            acc = acc + delta if (right - left) % 2 == 0 else acc - delta
            values.append(acc)
    assert int(run(x).strip()) == max(values)

def test_direct_definition(run, x):
    q = list(map(int, x.split()))
    n, a = q[0], q[1:]
    best = None
    for l in range(1, n + 1):
        for r in range(l + 1, n + 1):
            cur = sum(abs(a[i - 1] - a[i]) * (-1 if (i - l) % 2 else 1) for i in range(l, r))
            if best is None or cur > best:
                best = cur
    assert int(run(x).strip()) == best

def test_incremental_interval_oracle(run, x):
    v = list(map(int, x.split()))
    n, a = v[0], v[1:]
    best = -10**30
    for first_edge in range(n - 1):
        current = 0
        for edge in range(first_edge, n - 1):
            if edge % 2 == first_edge % 2:
                current += abs(a[edge] - a[edge + 1])
            else:
                current -= abs(a[edge] - a[edge + 1])
            if current > best:
                best = current
    assert int(run(x).strip()) == best

def test_explicit_sign_list(run, x):
    t = list(map(int, x.split()))
    n, a = t[0], t[1:]
    d = [abs(a[i + 1] - a[i]) for i in range(n - 1)]
    candidates = []
    for l in range(n - 1):
        signed = []
        for r in range(l, n - 1):
            signed.append(d[r] if len(signed) % 2 == 0 else -d[r])
            candidates.append(sum(signed))
    assert int(run(x).strip()) == max(candidates)

