def test_exhaustive_reversal_dp(run, x):
    a = list(map(int, x.splitlines()[1].split()))
    text = run(x).strip()
    assert len(text.split()) == 1
    got = int(text)
    best = 0
    for l in range(len(a)):
        for r in range(l, len(a)):
            b = a[:l] + a[l:r + 1][::-1] + a[r + 1:]
            dp = [1] * len(b)
            for i in range(len(b)):
                for j in range(i):
                    if b[j] <= b[i]:
                        dp[i] = max(dp[i], dp[j] + 1)
            best = max(best, max(dp))
    assert got == best


