def test_exact_definition_oracle(run, x):
    n = int(x.splitlines()[0])
    a = list(map(int, x.splitlines()[1].split()))
    text = run(x).strip()
    assert len(text.split()) == 1
    got = int(text)
    answer = 0
    for left in range(n):
        for right in range(left, n):
            changed = list(a)
            changed[left:right + 1] = reversed(changed[left:right + 1])
            longest = 0
            for mask in range(1 << n):
                previous = 0
                valid = True
                length = 0
                for i in range(n):
                    if mask & (1 << i):
                        if changed[i] < previous:
                            valid = False
                            break
                        previous = changed[i]
                        length += 1
                if valid:
                    longest = max(longest, length)
            answer = max(answer, longest)
    assert got == answer

