def test_sorted_subset_scan(run, x):
    data = list(map(int, x.split()))
    n, a = data[0], data[1:]
    total = 0
    for mask in range(1, 1 << n):
        low = None
        high = None
        for i, value in enumerate(a):
            if mask & (1 << i):
                low = value if low is None or value < low else low
                high = value if high is None or value > high else high
        total += high - low
    got = int(run(x).strip())
    assert got == total % 1000000007

def test_recursive_subsets(run, x):
