def test_explicit_minimum_maximum(run, x):
    data = list(map(int, x.split()))
    n, a = data[0], data[1:]
    total = 0
    for mask in range(1, 1 << n):
        values = [a[i] for i in range(n) if (mask & (1 << i)) != 0]
        minimum = values[0]
        maximum = values[0]
        for value in values[1:]:
            if value < minimum:
                minimum = value
            if value > maximum:
                maximum = value
        total += maximum - minimum
    got = int(run(x).strip())
    assert got == total % 1000000007

