def test_prefix_suffix_counts(run, x):
    z = list(map(int, x.split()))
    n, a = z[0], z[1:]
    want = 0
    for l in range(n):
        for r in range(l, n):
            b = a[:l] + list(reversed(a[l:r + 1])) + a[r + 1:]
            ones = 0
            twos = b.count(2)
            want = max(want, ones + twos)
            for v in b:
                if v == 1:
                    ones += 1
                else:
                    twos -= 1
                want = max(want, ones + twos)
    out = run(x).split()
    assert len(out) == 1 and out[0].isdigit()
    assert int(out[0]) == want


