    pairs = [tuple(map(lambda q: int(q)-1, s.split())) for s in lines[2:]]
    def squarefree(z):
        d = 2
        while d*d <= z:
            if z % (d*d) == 0: return False
            d += 1
        return True
    if all(squarefree(z) for z in a):
        primes = set()
