            best=0
            for mask in range(1<<m):
                used=[0]*n
                for q,(i,j) in enumerate(pairs):
                    if mask>>q&1 and a[i]%p==0 and a[j]%p==0: used[i]+=1; used[j]+=1
                    elif mask>>q&1: used=[2]*n; break
                if max(used, default=0)<=1: best=max(best, mask.bit_count())
            want+=best
        assert int(run(x).strip()) == want
    else: run(x)


def test_power_of_two_exhaustion(run, x):
